import json

LABELS = ["billing", "shipping", "technical", "other"]

def build_classify_prompt(message):
    labels = ", ".join(LABELS)
    return (
        f"Sort this customer message into one label: {labels}.\n"
        'Reply with JSON only, like {"label": "billing"}.\n\n'
        f"Message: {message}"
    )

def parse_reply(text):
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        return None
    return data if isinstance(data, dict) else None

def classify(model, message):
    data = parse_reply(model(build_classify_prompt(message)))
    if data and data.get("label") in LABELS:
        return data["label"]
    return "unknown"

def fake_model(prompt):
    text = prompt.split("Message:")[1].lower()
    if "refund" in text or "charge" in text:
        return '{"label": "billing"}'
    if "order" in text or "delivery" in text:
        return '{"label": "shipping"}'
    if "error" in text or "crash" in text:
        return '{"label": "technical"}'
    return "Sorry, no idea"

messages = [
    "I want a refund for my last charge",
    "Where is my order?",
    "The app shows an error on start",
    "Do you have a gift card?",
]
for m in messages:
    print(classify(fake_model, m), "<-", m)

