import json

LABELS = ["billing", "shipping", "technical", "other"]

def build_classify_prompt(message):
    labels = ", ".join(LABELS)
    return (
        f"Sort this customer message into one label: {labels}.\n"
        'Reply with JSON only, like {"label": "billing"}.\n\n'
        f"Message: {message}"
    )

def parse_reply(text):
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        return None
    return data if isinstance(data, dict) else None

def classify(model, message):
    data = parse_reply(model(build_classify_prompt(message)))
    if data and data.get("label") in LABELS:
        return data["label"]
    return "unknown"

def classify_with_retry(model, message, tries=2):
    for _ in range(tries):
        label = classify(model, message)
        if label != "unknown":
            return label
    return "unknown"

def sort_messages(model, messages):
    groups = {}
    for message in messages:
        label = classify_with_retry(model, message)
        groups.setdefault(label, []).append(message)
    return groups

