def make_report(groups):
    lines = []
    total = 0
    for label, items in sorted(groups.items(), key=lambda item: (-len(item[1]), item[0])):
        lines.append(f"{label}: {len(items)}")
        total += len(items)
    lines.append(f"Total: {total}")
    return "\n".join(lines)
